// Batch Input: the caller's passthrough item, one per call, exactly as the parent shaped it: one
// batch of companies (100, ruled 2026-09-08) with what People already holds at their domains, the
// base and table ids, and the key of the Hub row this pass writes: "<parentExecId>-<batchNum>".
// One mode, one machine (rebuilt 2026-09-08 as the Enrich Contacts Rootflow): every provider
// sub-workflow is asked for every company, the answers are merged on Contact Key and LinkedIn
// slug, the People writer upserts, the companies are stamped, a recount reports coverage.
// The key parts are required here, before any paid call; startedAt is the clock Duration s runs on.
const raw=$input.first().json||{};
const inp=Object.assign({}, raw);
const parentExecId=String(inp.parentExecId||'').trim();
const batchNum=Math.floor(Number(inp.batchNum)||0);
const who='Enrich Contacts Batch';
if(!parentExecId) throw new Error(who+' was called without parentExecId. Its Hub row is keyed by it. Nothing was pulled.');
if(!(batchNum>0)) throw new Error(who+' '+parentExecId+' was called without batchNum. Its Hub row is keyed "<parentExecId>-<batchNum>". Nothing was pulled.');
if(!/^app[A-Za-z0-9]{14}$/.test(String(inp.base||''))) throw new Error(who+' '+parentExecId+' has no valid base. Nothing was pulled.');
for(const k of ['peopleTableId','companiesTableId']){ if(!inp[k]) throw new Error(who+' '+parentExecId+' has no '+k+'. Nothing was pulled.'); }
if(!Array.isArray(inp.companies)||!inp.companies.length) throw new Error(who+' '+parentExecId+' received an empty company list. The parent must never send one.');
inp.parentExecId=parentExecId;
inp.batchNum=batchNum;
inp.logKey=parentExecId+'-'+String(batchNum);
inp.startedAt=new Date().toISOString();
return [{ json: inp }];

// Plan Batch: the companies in, the plan out. Ruled 2026-09-08: every provider is asked for every
// company; the only shaping is a cap per provider and a seniority floor, both read off the
// Employees value already on OUR Companies row (sources disagree on headcount, so the provider's
// own size is never consulted), in three coarse tiers so a one-band disagreement changes nothing:
//   up to 50 employees, or unknown   cap 20 per provider   floor "wide": everyone non-junior, senior ICs too
//   51 to 500                        cap 30 per provider   floor "nonjunior": everyone non-junior
//   501 and up                       cap 50 per provider   floor "manager": manager and up
// 50 is the ceiling because GetLeads' max_per_company hard-stops there. Each provider sub-workflow
// translates the floor into its own vocabulary. Pull WIDE, cut in the base: who gets messaged is
// the relevance formula and the views on People. No Tag: People stores none (a lookup).
const inp=$input.first().json||{};
const companies=Array.isArray(inp.companies)?inp.companies:[];
if(!companies.length) throw new Error('Enrich Contacts Batch received an empty company list. The parent must never send one.');
const BANDS=['1-10','11-50','51-200','201-500','501-1000','1001-5000','5001-10000','10001+'];
const band=(v)=>{ const s=String(v==null?'':v).trim(); if(!s) return ''; if(BANDS.indexOf(s)>-1) return s; const n=Number(s.replace(/[,\s+]/g,'')); if(!isFinite(n)||n<=0) return ''; if(n<=10) return '1-10'; if(n<=50) return '11-50'; if(n<=200) return '51-200'; if(n<=500) return '201-500'; if(n<=1000) return '501-1000'; if(n<=5000) return '1001-5000'; if(n<=10000) return '5001-10000'; return '10001+'; };
const tier=(b)=>{ if(!b||b==='1-10'||b==='11-50') return { cap:20, floor:'wide' }; if(b==='51-200'||b==='201-500') return { cap:30, floor:'nonjunior' }; return { cap:50, floor:'manager' }; };
const plan=companies.map(c=>{ const b=band(c.employees); const t=tier(b); return {
  recordId:c.recordId, domain:String(c.domain||'').trim().toLowerCase(), company:String(c.company||'').trim(),
  band:b||'unknown', cap:t.cap, floor:t.floor,
  heldRows:Array.isArray(c.heldRows)?c.heldRows:[]
}; }).filter(c=>c.domain);
const tiers={ wide:0, nonjunior:0, manager:0 }; for(const c of plan) tiers[c.floor]++;
return [{ json: {
  batchNum:Number(inp.batchNum)||0, batchCount:Number(inp.batchCount)||0,
  plan:plan, companies:plan.map(c=>({ recordId:c.recordId, domain:c.domain, company:c.company, band:c.band, cap:c.cap, floor:c.floor })),
  tiers:tiers, capRule:'up to 50 employees or unknown: 20 wide; 51 to 500: 30 non-junior; 501 and up: 50 manager and up'
} }];

// Plan Ready: the DNC read sits between Plan Batch and the tiers so both DNC passes share it;
// re-emit the plan as the one item the gates read, so no gate ever evaluates against DNC rows.
return [{ json: $('Plan Batch').first().json }];

// Apply DNC: drops people whose domain sits on the client's DNC table (every page of it, read once
// by Get DNC Domains); the domain is the _domain carrier Merge People set, backed by a Contact Key
// -> domain map read straight from the merge in case the helper dropped the carrier. Then fences
// the write set to exactly what this machine writes on People (ruled 2026-09-02): Name, Title,
// Seniority, Department, Email, LinkedIn URL, Phone, Companies, Contact Key, Contact Source,
// Source ID, plus first_name and last_name, the split Clean Fields made from Name. The _id carrier
// (a held row being updated) rides through to the writer. Domain, Company and Tag are lookups
// through the Companies link and are never written; every other key is stripped, and a key the
// table does not carry is stripped too. Zero survivors still emit one {_empty} placeholder.
const WRITE_FIELDS=['Name','first_name','last_name','Title','Seniority','Department','Email','LinkedIn URL','Phone','Companies','Contact Key','Contact Source','Source ID'];
const have=new Set(($('Batch Input').first().json.peopleFields)||[]);
const allow=new Set(WRITE_FIELDS.filter(k=>have.has(k)));
const dnc=new Set();
try{ for(const it of $('Get DNC Domains').all()){ const j=it.json||{}; const f=j.fields||{}; const d=String(f.Domain||f.domain||'').toLowerCase().trim(); if(d) dnc.add(d); } }catch(e){}
const domainByKey={};
try{ for(const it of $('Merge People').all()){ const j=it.json||{}; const k=String(j['Contact Key']||'').toLowerCase(); if(k&&j._domain) domainByKey[k]=String(j._domain).toLowerCase(); } }catch(e){}
const out=[];
for(const i of $('Clean Fields').all()){
  const j=i.json||{};
  if(j._empty) continue;
  const key=String(j['Contact Key']||'').toLowerCase().trim();
  if(!key) continue;
  const d=String(j._domain||domainByKey[key]||'').toLowerCase().trim();
  if(dnc.size&&d&&dnc.has(d)) continue;
  const row={};
  for(const k of Object.keys(j)){ if(allow.has(k)) row[k]=j[k]; }
  if(j._id) row._id=j._id;
  out.push({ json: row });
}
if(!out.length) return [{ json:{ _empty:true } }];
return out;

// Chunk People: the survivors of Apply DNC in tens, one item per Airtable request. Write People
// PATCHes each as {performUpsert: {fieldsToMergeOn: ["Contact Key"]}, records, typecast} at 200 ms
// apart, ten records per request at five requests per second. A new person is a record without an
// id (matched on Contact Key); a held person being filled (the _id carrier from Merge People) is a
// record WITH its id, which Airtable treats as a plain update inside the same request. The Contact
// Keys and the size ride on the item, never in the body, for the count-back.
const rows=$input.all().map(i=>i.json).filter(j=>j&&!j._empty&&j['Contact Key']);
const out=[];
for(let i=0;i<rows.length;i+=10){
  const part=rows.slice(i,i+10);
  out.push({ json: {
    body: { performUpsert: { fieldsToMergeOn: ['Contact Key'] }, records: part.map(r=>{ const f=Object.assign({}, r); const id=f._id; delete f._id; return id?{ id:id, fields:f }:{ fields:f }; }), typecast: true },
    keys: part.map(r=>String(r['Contact Key']).toLowerCase()),
    updates: part.filter(r=>r._id).length,
    size: part.length
  } });
}
return out;

// Stamp Rows: Contacts Pulled At = now on every company in the batch, tried or not, found or
// not, in tens, one item per Airtable request (Stamp Companies PATCHes each by record id, typecast
// on, 200 ms apart). The Not Sourced view drops them; Not Covered keeps the zero-contact ones
// visible. Writer mode only: the ark pass stamps nothing new.
const plan=$('Plan Batch').first().json;
const now=new Date().toISOString();
const ids=plan.plan.map(c=>c.recordId).filter(Boolean);
const out=[];
for(let i=0;i<ids.length;i+=10){
  const part=ids.slice(i,i+10);
  out.push({ json: { body: { records: part.map(id=>({ id: id, fields: { 'Contacts Pulled At': now } })), typecast: true }, size: part.length } });
}
return out;

// Recount Filters: after the writer's stamps, read People again for the batch's domains, ids
// only (Contact Key, LinkedIn URL, Domain), one OR formula per 100 domains: the batch's coverage
// is what the base holds now, and the same held state goes back to the parent, which hands it to
// this batch's AI-Ark pass so AI-Ark is sized to the gap and its exclude list is exact. Domain on
// People is a lookup through the Companies link; filterByFormula {Domain}='x' matches the lookup's
// text, so the read works unchanged.
const plan=$('Plan Batch').first().json;
const d=plan.plan.map(c=>c.domain);
const esc=(s)=>String(s).replace(/\\/g,'\\\\').replace(/'/g,"\\'");
const out=[];
for(let i=0;i<d.length;i+=100){
  const chunk=d.slice(i,i+100);
  out.push({ json: { formula: chunk.length===1?("{Domain}='"+esc(chunk[0])+"'"):('OR('+chunk.map(x=>"{Domain}='"+esc(x)+"'").join(',')+')') } });
}
if(!out.length) out.push({ json: { formula: "{Domain}=''" } });
return out;

// Batch Summary: the counters of this pass, and the ONLY thing that crosses back to the parent
// (through Batch Response, after this pass's own Hub row is written). Per provider: the verdict
// its sub-workflow answered with (ok, skipped with a reason, error with a cause) and its counters.
// Written rows are counted from the writer's answers (records[] of every 2xx PATCH), never from
// item ids; a request that was not 2xx counts every record it carried as a write error with the
// HTTP reason (never retried: a 429 locks Airtable for 30 s). Coverage reads the recount taken
// after the stamps. allFailed means every provider that was actually asked answered error (a skip
// is not a failure): the parent then stops launching batches.
const inp=$('Batch Input').first().json;
const plan=$('Plan Batch').first().json;
const n=(v)=>Number(v)||0;
const PRIORITY=['Blitz','GetLeads','QuickEnrich','Supersoniq'];
const NODE={ Blitz:'Run Blitz', GetLeads:'Run GetLeads', QuickEnrich:'Run QuickEnrich', Supersoniq:'Run Supersoniq' };
const providers={};
for(const p of PRIORITY){
  let j=null; try{ j=$(NODE[p]).first().json||null; }catch(e){ j=null; }
  const s=(j&&j.stats)||{};
  if(!j) providers[p]={ status:'skipped', reason:'not run', called:0, returned:0, kept:0, credits:0, errors:0, firstError:'', failReasons:[] };
  else if(j.error&&!j.provider) providers[p]={ status:'error', reason:'sub-workflow crashed: '+String((j.error&&(j.error.message||j.error.description))||j.error).slice(0,160), called:0, returned:0, kept:0, credits:0, errors:1, firstError:String((j.error&&j.error.message)||'crashed').slice(0,160), failReasons:[] };
  else providers[p]={ status:String(j.status||'ok'), reason:String(j.reason||''), called:n(s.called), returned:n(s.returned), kept:n(s.kept), credits:Math.round(n(s.credits)*100)/100, errors:n(s.errors), firstError:String(s.firstError||''), failReasons:(Array.isArray(s.failReasons)?s.failReasons:[]).slice(0,5), extra:{ dropped:n(s.dropped), emailBlanked:n(s.emailBlanked), resolved:n(s.resolved), unresolved:n(s.unresolved), rosterRows:n(s.rosterRows), emails:n(s.emails), pages:n(s.pages), noKey:n(s.noKey) } };
}
let merge={}; try{ const j=$('Merge People').first().json||{}; merge=j._stats||{}; }catch(e){}
const rowsOf=(name)=>{ try{ return $(name).all().filter(i=>i.json&&!i.json._empty&&i.json['Contact Key']).length; }catch(e){ return 0; } };
const dnc=Math.max(0, rowsOf('Clean Fields')-rowsOf('Apply DNC'));
const domainByKey={};
try{ for(const it of $('Merge People').all()){ const j=it.json||{}; const k=String(j['Contact Key']||'').toLowerCase(); if(k&&j._domain) domainByKey[k]=String(j._domain).toLowerCase(); } }catch(e){}
const parse=(b)=>{ if(typeof b!=='string') return b; try{ return JSON.parse(b); }catch(e){ return null; } };
const failReasons=[];
const reason=(prefix,j,b,status)=>{ const e=b&&b.error; const why=e?(typeof e==='object'?(e.message||e.type||JSON.stringify(e)):String(e)):((j.error&&j.error.message)||(typeof j.body==='string'?j.body:'')); return (prefix+' HTTP '+status+' '+String(why||'').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim()).slice(0,180)+(status===429?' (rate limited; never retried)':''); };
let written=0, updatedWritten=0, writeErrors=0; const writtenByDomain={};
let chunks=[], resps=[];
try{ chunks=$('Chunk People').all().map(i=>i.json); resps=$('Write People').all(); }catch(e){}
resps.forEach((it,i)=>{
  const c=chunks[i]||{ size:0, keys:[], updates:0 }; const j=it.json||{};
  if(j.error&&j.statusCode===undefined){ writeErrors+=n(c.size); if(failReasons.length<10) failReasons.push('People writer: '+String((j.error&&j.error.message)||'call failed').slice(0,160)); return; }
  const status=n(j.statusCode); const b=parse(j.body===undefined?null:j.body);
  if(status>=200&&status<300&&b&&Array.isArray(b.records)){
    written+=b.records.length; updatedWritten+=n(c.updates);
    for(const r of b.records){ const k=String(((r||{}).fields||{})['Contact Key']||'').toLowerCase(); const d=domainByKey[k]||''; if(d) writtenByDomain[d]=(writtenByDomain[d]||0)+1; }
    if(b.records.length<n(c.size)){ writeErrors+=n(c.size)-b.records.length; if(failReasons.length<10) failReasons.push('People writer: '+(n(c.size)-b.records.length)+' of '+c.size+' records missing from a 2xx answer'); }
    return;
  }
  writeErrors+=n(c.size);
  if(failReasons.length<10) failReasons.push(reason('People writer',j,b,status));
});
let stamped=0, stampErrors=0; let sChunks=[], sResps=[];
try{ sChunks=$('Stamp Rows').all().map(i=>i.json); sResps=$('Stamp Companies').all(); }catch(e){}
sResps.forEach((it,i)=>{
  const c=sChunks[i]||{ size:0 }; const j=it.json||{};
  if(j.error&&j.statusCode===undefined){ stampErrors+=n(c.size); if(failReasons.length<10) failReasons.push('Contacts Pulled At stamp: '+String((j.error&&j.error.message)||'call failed').slice(0,160)); return; }
  const status=n(j.statusCode); const b=parse(j.body===undefined?null:j.body);
  if(status>=200&&status<300&&b&&Array.isArray(b.records)){ stamped+=b.records.length; if(b.records.length<n(c.size)) stampErrors+=n(c.size)-b.records.length; return; }
  stampErrors+=n(c.size);
  if(failReasons.length<10) failReasons.push(reason('Contacts Pulled At stamp',j,b,status));
});
const held={}; let recountRows=0;
const domainOf=(f)=>{ const v=f.Domain; return String(Array.isArray(v)?(v[0]||''):(v||'')).trim().toLowerCase(); };
try{ for(const it of $('Recount People').all()){ const j=it.json||{}; if(!j.id) continue; const f=j.fields||{}; const d=domainOf(f); if(!d) continue; const h=held[d]||(held[d]={ count:0 }); h.count++; recountRows++; } }catch(e){}
let covered=0; const zeroDomains=[];
for(const c of plan.plan){
  const have=((held[c.domain]||{}).count||0)+(writtenByDomain[c.domain]||0)+(!recountRows?(c.heldRows||[]).length:0);
  if(have>0) covered++; else if(zeroDomains.length<50) zeroDomains.push(c.domain);
}
const asked=PRIORITY.filter(p=>providers[p].status!=='skipped');
const allFailed=asked.length>0&&asked.every(p=>providers[p].status==='error');
for(const p of PRIORITY) for(const r of providers[p].failReasons) if(failReasons.length<10) failReasons.push(String(r));
return [{ json: {
  mode:'writer', batchNum: plan.batchNum, batchCount: plan.batchCount, logKey: inp.logKey,
  companiesIn: plan.plan.length, tiers: plan.tiers,
  providers: providers,
  returned: n(merge.returned), built: n(merge.built), updated: n(merge.updated), heldUnchanged: n(merge.heldUnchanged), dupes: n(merge.dupes), noKey: n(merge.noKey), fenced: n(merge.fenced), emailsAppended: n(merge.emailsAppended), singleSelectSource: !!merge.singleSelectSource, perProvider: merge.perProvider||{}, dnc: dnc,
  written: written, updatedWritten: updatedWritten, writeErrors: writeErrors, writeRequests: resps.length, stamped: stamped, stampErrors: stampErrors,
  covered: covered, zero: plan.plan.length-covered, zeroDomains: zeroDomains,
  allFailed: allFailed, failReasons: failReasons
} }];

// Build Batch Log: this pass's own Hub row: Execution ID "<parentExecId>-<n>", Automation
// "Enrich Contacts Batch", Client attached, Records In = companies in, Records Out = people
// written, Description = one line per provider (its verdict and counters) then the merge, the
// writer, the stamps and the coverage; Tally = the counters JSON the parent sums once every pass
// row landed. Status computed: Failed when every provider that was asked answered error (the pass
// did no work; the parent stops launching), Succeeded with errors when failed[] is not empty,
// Succeeded otherwise. A provider that was skipped (no credential, out of credits, nothing to
// ask) is a Skipped line, never an error (ruled 2026-09-08: the run moves on).
const inp=$('Batch Input').first().json;
const s=Object.assign({}, $('Batch Summary').first().json||{});
const num=(v)=>Number(v)||0;
const PRIORITY=['Blitz','GetLeads','QuickEnrich','Supersoniq'];
const failed=[]; const skips=[];
for(const p of PRIORITY){
  const x=(s.providers||{})[p]||{};
  if(x.status==='skipped'){ skips.push(p+': '+(x.reason||'skipped')); continue; }
  if(x.status==='error'){ failed.push({ tier:p, reason:x.reason||x.firstError||'failed' }); continue; }
  for(let i=0;i<num(x.errors);i++) failed.push({ tier:p, reason:x.firstError||'call failed' });
}
for(let i=0;i<num(s.writeErrors);i++) failed.push({ tier:'People writer', reason:'row not in the answer' });
for(let i=0;i<num(s.stampErrors);i++) failed.push({ tier:'Contacts Pulled At stamp', reason:'row not in the answer' });
let dur=0; try{ dur=Math.max(0,Math.round(($now.toMillis()-new Date(inp.startedAt).getTime())/1000)); }catch(e){}
const companiesIn=num(s.companiesIn), covered=num(s.covered), pct=companiesIn?Math.round(100*covered/companiesIn):0;
const line=(p)=>{ const x=(s.providers||{})[p]||{}; const e=x.extra||{}; if(x.status==='skipped') return '- **'+p+':** skipped ('+(x.reason||'')+')'; if(x.status==='error') return '- **'+p+':** failed ('+(x.reason||x.firstError||'')+')'; const bits=['called '+num(x.called),'returned '+num(x.returned),'kept '+num(x.kept)]; if(num(x.credits)) bits.push('credits '+x.credits); if(num(e.resolved)||num(e.unresolved)) bits.push(num(e.resolved)+' companies resolved on LinkedIn, '+num(e.unresolved)+' not'); if(num(e.rosterRows)) bits.push('roster '+num(e.rosterRows)+', emails '+num(e.emails)); if(num(e.dropped)) bits.push(num(e.dropped)+' at domains not asked dropped'); if(num(e.emailBlanked)) bits.push(num(e.emailBlanked)+' foreign-domain emails blanked'); if(num(x.errors)) bits.push('errors '+num(x.errors)); return '- **'+p+':** '+bits.join(', '); };
const t=s.tiers||{};
const lines=[ '**Batch '+num(s.batchNum)+' of '+num(s.batchCount)+': '+companiesIn+' companies in, '+num(s.built)+' people new, '+num(s.updated)+' held people filled, '+num(s.written)+' rows written, '+covered+' of '+companiesIn+' covered ('+pct+'%)**', '',
  '**Parent run:** '+inp.parentExecId+' (this row is one pass of it; the parent sums the passes)',
  '**Cap and floor:** '+String(s.capRule||'up to 50 employees or unknown: 20 wide; 51 to 500: 30 non-junior; 501 and up: 50 manager and up')+' (this batch: '+num(t.wide)+' wide, '+num(t.nonjunior)+' non-junior, '+num(t.manager)+' manager and up)',
  '', '**Providers (every one asked for every company; priority Blitz, GetLeads, QuickEnrich, Supersoniq)**' ];
for(const p of PRIORITY) lines.push(line(p));
lines.push('', '**Merge**');
lines.push('- **Returned:** '+num(s.returned)+' people across providers; **new rows:** '+num(s.built)+'; **held rows filled:** '+num(s.updated)+' ('+num(s.emailsAppended)+' emails appended); **held unchanged:** '+num(s.heldUnchanged)+'; **same person from two providers:** '+num(s.dupes)+' merged; **no usable first name:** '+num(s.noKey)+'; **LinkedIn URLs rejected by the name fence:** '+num(s.fenced)+'; **on the DNC table:** '+num(s.dnc));
const pp=s.perProvider||{};
lines.push('- **Per provider:** '+PRIORITY.map(p=>{ const x=pp[p]||{}; return p+' '+num(x.newRows)+' new / '+num(x.mergedInto)+' merged'; }).join('; '));
if(s.singleSelectSource) lines.push('- **Contact Source is a single select on this base:** only the first source per person was recorded; retype it to a multi-select to record every provider');
lines.push('- **Written (rows in the writer\'s answers):** '+num(s.written)+' in '+num(s.writeRequests)+' requests of up to ten ('+num(s.updatedWritten)+' updates of held rows)');
lines.push('- **Coverage:** '+covered+' of '+companiesIn+' companies with at least one person ('+pct+'%)');
const zd=Array.isArray(s.zeroDomains)?s.zeroDomains:[];
lines.push('- **Zero-contact companies:** '+num(s.zero)+(zd.length?' ('+zd.slice(0,20).join(', ')+(zd.length>20?', ...':'')+')':''));
lines.push('- **Contacts Pulled At stamped:** '+num(s.stamped));
if(skips.length) lines.push('', '**Skipped ('+skips.join('; ')+')**');
if(s.allFailed) lines.push('', '**Every provider that was asked failed. The parent launches no further batches.**');
if(failed.length){
  const byReason={}; for(const f of failed){ const k=f.tier+': '+f.reason; byReason[k]=(byReason[k]||0)+1; }
  lines.push('', '**Failures ('+failed.length+')**');
  for(const [r,c] of Object.entries(byReason).slice(0,10)) lines.push('- '+c+' x '+r);
  for(const r of (Array.isArray(s.failReasons)?s.failReasons:[]).slice(0,5)) lines.push('- '+r);
}
const status=s.allFailed?'Failed':(failed.length?'Succeeded with errors':'Succeeded');
const log={
  'Execution ID': String(inp.logKey),
  'Automation': 'Enrich Contacts Batch',
  'Status': status,
  'Trigger': 'event',
  'Errors': failed.length,
  'Run at': inp.startedAt,
  'Target': (inp.peopleTableName||'People')+' ('+(inp.peopleTableId||'')+')',
  'Records In': companiesIn,
  'Records Out': num(s.written),
  'Duration s': dur,
  'Description': lines.join('\n'),
  'Tally': JSON.stringify(s),
  'Execution Link': 'https://n8n.flowroots.com/workflow/'+$workflow.id+'/executions/'+$execution.id
};
if(inp.clientRecId) log['Client']=[inp.clientRecId];
return [{ json: log }];

// Batch Response: the last node, so its output is what Execute Workflow hands back to the parent:
// the counters (Batch Summary), never rows. It runs after Log Batch, so this pass's Hub row exists
// before the parent hears back and the parent's close reads it by prefix.
return [{ json: $('Batch Summary').first().json }];

// Provider Input: the one item every provider sub-workflow receives, the plan's companies (domain,
// cap, floor) and nothing else. Re-emitted before each Run node because Execute Workflow passes
// its own input through, and the previous provider's answer must never be the next one's input.
const plan=$('Plan Ready').first().json||{};
return [{ json:{ companies:plan.companies||[], batchNum:plan.batchNum||0 } }];

// Provider Input: the one item every provider sub-workflow receives, the plan's companies (domain,
// cap, floor) and nothing else. Re-emitted before each Run node because Execute Workflow passes
// its own input through, and the previous provider's answer must never be the next one's input.
const plan=$('Plan Ready').first().json||{};
return [{ json:{ companies:plan.companies||[], batchNum:plan.batchNum||0 } }];

